 1	// @vitest-environment jsdom
 2	
 3	/**
 4	 * WP-005: Integration tests for the assembled auto-update behavior of
 5	 * views/project-detail.js.
 6	 *
 7	 * Coverage areas:
 8	 *   1. DOM element identity preservation during polling (strict === checks)
 9	 *   2. Synthesis auto-reveal without full page rerender or loss of inline editor state
10	 *   3. Project status badge updates in-place when status changes (data-only)
11	 *   4. Health badge updates in-place when health overview changes (data-only)
12	 *   5. WP pipeline stage badge transitions update in the existing row without
13	 *      replacing the table element or row node
14	 *
15	 * Uses jsdom + vm.runInThisContext following the pattern documented in
16	 * mcp-server/tests/gui/README.md.
17	 */
18	
19	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
20	import { readFileSync } from 'node:fs';
21	import { join } from 'node:path';
22	import vm from 'node:vm';
23	
24	// ---------------------------------------------------------------------------
25	// Load client scripts
26	// ---------------------------------------------------------------------------
27	
28	const publicDir = join(__dirname, '../../gui/public');
29	const projectDetailJs = readFileSync(join(publicDir, 'views/project-detail.js'), 'utf-8');
30	
31	beforeAll(() => {
32	  (globalThis as Record<string, unknown>)['marked'] = {
33	    parse: (s: string) => '<p>' + s + '</p>',
34	  };
35	
36	  (globalThis as Record<string, unknown>)['OrchestratorWidgets'] = {
37	    renderStatusCard:    vi.fn().mockReturnValue('<div class="orchestrator-status-card">card</div>'),
38	    renderKillButton:    vi.fn().mockImplementation((_id: string, _cb: () => void) => {
39	      const btn = document.createElement('button');
40	      btn.className = 'kill-btn';
41	      btn.textContent = 'Kill';
42	      return btn;
43	    }),
44	    renderDismissButton: vi.fn(),
45	    renderLogPreview:    vi.fn().mockReturnValue(vi.fn()),
46	    renderProgressBadge: vi.fn().mockReturnValue(''),
47	    renderCliReference:  vi.fn().mockReturnValue(''),
48	  };
49	
50	  (globalThis as Record<string, unknown>)['Router'] = {
51	    _setPolling:   vi.fn(),
52	    _clearPolling: vi.fn(),
53	  };
54	
55	  vm.runInThisContext(projectDetailJs);
56	});
57	
58	beforeEach(() => {
59	  vi.clearAllMocks();
60	  globalThis.OrchestratorWidgets.renderStatusCard

 61	    .mockReturnValue('<div class="orchestrator-status-card">card</div>');
 62	  globalThis.OrchestratorWidgets.renderLogPreview.mockReturnValue(vi.fn());
 63	  globalThis.OrchestratorWidgets.renderKillButton
 64	    .mockImplementation((_id: string, _cb: () => void) => {
 65	      const btn = document.createElement('button');
 66	      btn.className = 'kill-btn';
 67	      btn.textContent = 'Kill';
 68	      return btn;
 69	    });
 70	});
 71	
 72	// ---------------------------------------------------------------------------
 73	// Global type declarations
 74	// ---------------------------------------------------------------------------
 75	
 76	declare global {
 77	  // eslint-disable-next-line no-var
 78	  var renderProjectDetail: (app: HTMLElement, repo: string, slug: string) => void;
 79	  // eslint-disable-next-line no-var
 80	  var _pollProjectDetail: (
 81	    app: HTMLElement,
 82	    repo: string,
 83	    slug: string,
 84	    pollStateRef: unknown[],
 85	    pollController: Record<string, unknown>
 86	  ) => void;
 87	  // eslint-disable-next-line no-var
 88	  var _snapshotProjectState: (
 89	    project: Record<string, unknown>,
 90	    overviewResult: unknown[] | null
 91	  ) => {
 92	    status: string;
 93	    last_updated: string;
 94	    synthesis_generated: boolean;
 95	    wpStatuses: Record<string, { status: string; pipelineStages: unknown[] }>;
 96	    health: null | { work_packages_needing_reset: number };
 97	  };
 98	  // eslint-disable-next-line no-var
 99	  var API: Record<string, Mock>;
100	  // eslint-disable-next-line no-var
101	  var OrchestratorWidgets: {
102	    renderStatusCard:    Mock;
103	    renderKillButton:    Mock;
104	    renderDismissButton: Mock;
105	    renderLogPreview:    Mock;
106	    renderProgressBadge: Mock;
107	    renderCliReference:  Mock;
108	  };
109	  // eslint-disable-next-line no-var
110	  var Router: {
111	    _setPolling:   Mock;
112	    _clearPolling: Mock;
113	  };
114	}
115	
116	// ---------------------------------------------------------------------------
117	// Helpers
118	// ---------------------------------------------------------------------------
119	
120	function makeProject(overrides: Record<string, unknown> = {}) {
121	  return {
122	    meta: {
123	      status: 'IN_PROGRESS',
124	      title: 'Test Project',
125	      plan_path: '/some/path',
126	      date_created: '2026-01-01T00:00:00Z',
127	      last_updated: '2026-01-01T00:00:00Z',
128	      ...(overrides._metaOverrides as Record<string, unknown> ?? {}),
129	      ...overrides,
130	    },
131	    work_packages: (overrides.work_packages as unknown[] | undefined) ?? [],
132	    project_comments: [],
133	    project_name: 'Test Project',
134	    timing: null,
135	    server_version: null,
136	    ledger_version: null,
137	    synthesis_generated: !!(overrides.synthesis_generated),
138	    ...(overrides._rootOverrides as Record<string, unknown> ?? {}),
139	  };
140	}
141	
142	/** Minimal no-op pollController for direct _pollProjectDetail calls. */
143	function makeNoopPollController() {
144	  return {
145	    getMode:              vi.fn().mockReturnValue('combined'),
146	    startCombinedPolling: vi.fn(),
147	    startResumePolling:   vi.fn(),
148	    settleResumePolling:  vi.fn(),
149	    stopPolling:          vi.fn(),
150	  };
151	}
152	
153	/**
154	 * Render the project detail page and wait for all async chains to settle.
155	 * Returns once the orchestrator-runs-section no longer shows the loading
156	 * placeholder, plus a few extra ticks for trailing microtasks.
157	 */
158	async function renderAndSettle(
159	  app: HTMLElement,
160	  repo: string,

161	  slug: string,
162	  apiStubs: Partial<{
163	    getProject: Mock;
164	    getPlanDocument: Mock;
165	    getWorkPackageOverview: Mock;
166	    getProjectHealth: Mock;
167	    getRunLogs: Mock;
168	    orchestratorGetQueue: Mock;
169	    getRunMetadata: Mock;
170	    orchestratorStart: Mock;
171	    analyzeProjectReset: Mock;
172	  }> = {}
173	): Promise<void> {
174	  (globalThis as Record<string, unknown>)['API'] = {
175	    getProject:             apiStubs.getProject           ?? vi.fn().mockResolvedValue(makeProject()),
176	    getPlanDocument:        apiStubs.getPlanDocument       ?? vi.fn().mockRejectedValue({ code: 'NOT_FOUND' }),
177	    getWorkPackageOverview: apiStubs.getWorkPackageOverview ?? vi.fn().mockResolvedValue(null),
178	    getProjectHealth:       apiStubs.getProjectHealth      ?? vi.fn().mockResolvedValue({ work_packages_needing_reset: 0 }),
179	    getRunLogs:             apiStubs.getRunLogs            ?? vi.fn().mockResolvedValue([]),
180	    orchestratorGetQueue:   apiStubs.orchestratorGetQueue  ?? vi.fn().mockResolvedValue([]),
181	    getRunMetadata:         apiStubs.getRunMetadata        ?? vi.fn().mockRejectedValue(new Error('no meta')),
182	    orchestratorStart:      apiStubs.orchestratorStart     ?? vi.fn().mockRejectedValue(new Error('not stubbed')),
183	    analyzeProjectReset:    apiStubs.analyzeProjectReset   ?? vi.fn().mockRejectedValue(new Error('not stubbed')),
184	  };
185	
186	  globalThis.renderProjectDetail(app, repo, slug);
187	
188	  const deadline = Date.now() + 300;
189	  while (Date.now() < deadline) {
190	    await new Promise<void>((r) => setTimeout(r, 10));
191	    const el = app.querySelector('#orchestrator-runs-section');
192	    if (!el || !el.innerHTML.includes('Loading runs')) break;
193	  }
194	  await new Promise<void>((r) => setTimeout(r, 20));
195	}
196	
197	// ---------------------------------------------------------------------------
198	// §1 DOM element identity preservation (AC-4)
199	// ---------------------------------------------------------------------------
200	
201	describe('WP-005 — DOM element identity preservation during poll ticks (AC-4)', () => {
202	  let app: HTMLElement;
203	
204	  beforeEach(() => {
205	    app = document.createElement('div');
206	    document.body.appendChild(app);
207	  });
208	  afterEach(() => { if (app.parentNode) app.parentNode.removeChild(app); });
209	
210	  it('WP table row === identity is preserved after a data-only poll tick (status change)', async () => {
211	    // Render the page with one WP
212	    const wp = { work_package_id: 'WP-001', status: 'READY', assigned_to: 'Developer' };
213	    const project = { ...makeProject(), work_packages: [wp] };
214	
215	    await renderAndSettle(app, 'repo', 'proj', {
216	      getProject: vi.fn().mockResolvedValue(project),
217	    });
218	
219	    // Capture the row element reference before the poll tick
220	    const rowBefore = app.querySelector('tr[data-wp-id="WP-001"]') as HTMLElement;
221	    expect(rowBefore).not.toBeNull();
222	
223	    // Simulate a data-only poll tick: same WP count, but status changes
224	    const updatedProject = { ...project, work_packages: [{ ...wp, status: 'IN_PROGRESS' }] };
225	    (globalThis as Record<string, unknown>)['API'] = {
226	      getProject:             vi.fn().mockResolvedValue(updatedProject),
227	      getWorkPackageOverview: vi.fn().mockResolvedValue(null),
228	      getProjectHealth:       vi.fn().mockResolvedValue({ work_packages_needing_reset: 0 }),
229	    };
230	
231	    const snapshot = globalThis._snapshotProjectState(project, null);
232	    const pollStateRef: unknown[] = [snapshot];
233	    const ctrl = makeNoopPollController();
234	
235	    globalThis._pollProjectDetail(app, 'repo', 'proj', pollStateRef, ctrl);
236	    await new Promise<void>((r) => setTimeout(r, 60));
237	
238	    // The same row element must still be in the DOM — identity preserved
239	    const rowAfter = app.querySelector('tr[data-wp-id="WP-001"]') as HTMLElement;
240	    expect(rowAfter).not.toBeNull();
241	    expect(rowAfter === rowBefore).toBe(true); // strict === reference equality
242	
243	    // The status badge inside the row should reflect the updated status
244	    const statusCell = rowAfter.querySelector('.wp-status-cell') as HTMLElement;
245	    expect(statusCell.innerHTML).toContain('IN_PROGRESS');
246	  });
